-- LOCAL database only. All fixtures and mutations are rolled back.
begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select plan(45);
insert into auth.users(id,email,raw_user_meta_data)values
 ('fdf00000-0000-4000-8000-000000000001','companion1@example.invalid','{"username":"companion_one"}'),
 ('fdf00000-0000-4000-8000-000000000002','companion2@example.invalid','{"username":"companion_two"}'),
 ('fdf00000-0000-4000-8000-000000000003','companion3@example.invalid','{"username":"companion_three"}'),
 ('fdf00000-0000-4000-8000-000000000004','companion4@example.invalid','{"username":"companion_admin"}');
update public.profiles set role='admin' where id='fdf00000-0000-4000-8000-000000000004';
select set_config('request.jwt.claim.sub','fdf00000-0000-4000-8000-000000000001',true);
set local role authenticated;
select is(public.save_companion_section('tasks','[]',0)->>'version','1','first save starts at version one');
select throws_ok($$select public.save_companion_section('tasks','[]',0)$$,'P0001','companion_conflict','stale first write is rejected');
select is(public.save_companion_section('tasks','[]',1)->>'version','2','current version can update');
select throws_ok($$select public.save_companion_section('unknown','[]',0)$$,'22023',null,'unknown sections cannot be saved');
select throws_ok($$select public.save_companion_section('wallet','{}',0)$$,'22023',null,'wrong payload shape is rejected');
select throws_ok($$insert into public.companion_sections(user_id,section,payload)values('fdf00000-0000-4000-8000-000000000002','tasks','[]')$$,'42501',null,'direct writes cannot bypass ownership or version checks');
select throws_ok($$update public.companion_sections set version=99$$,'42501',null,'direct version changes are blocked');
select is((select count(*)::int from public.companion_sections),1,'owner reads own section');
-- Store circle ID through a transaction-local setting, not a publicly accessible fixture table.
select set_config('fixture.circle',public.create_campus_circle(jsonb_build_object('title','Small study circle','description','Let us review networks together.','kind','study','location','Library tables','starts_at',now()+interval '1 day','duration',25,'capacity',2))->>'id',true);
select is(public.list_campus_circles()->0->>'members','1','host occupies one seat');
select throws_ok($$select public.act_campus_circle(current_setting('fixture.circle')::uuid,'leave')$$,'P0001','circle_host','host cannot leave an orphan gathering');
reset role;
select set_config('request.jwt.claim.sub','fdf00000-0000-4000-8000-000000000002',true);
set local role authenticated;
select is((select count(*)::int from public.companion_sections),0,'another user cannot read private plan');
select is(public.save_companion_section('tasks','[]',0)->>'version','1','another user has independent versions');
select lives_ok($$select public.act_campus_circle(current_setting('fixture.circle')::uuid,'join')$$,'student joins the final seat');
select lives_ok($$select public.act_campus_circle(current_setting('fixture.circle')::uuid,'join')$$,'retrying join is idempotent');
select is(public.list_campus_circles()->0->>'members','2','retry does not consume another seat');
select is((select count(*)::int from public.campus_circle_members),1,'member table reveals only own membership');
select ok(not(public.list_campus_circles()->0 ? 'host_id')and not(public.list_campus_circles()->0 ? 'user_id'),'public payload excludes auth identifiers');
select throws_ok($$select public.act_campus_circle(current_setting('fixture.circle')::uuid,'close')$$,'42501',null,'ordinary member cannot close circle');
select lives_ok($$select public.report_campus_circle(current_setting('fixture.circle')::uuid,'Please inspect this gathering')$$,'student can send a private report');
select lives_ok($$select public.report_campus_circle(current_setting('fixture.circle')::uuid,'Retry same pending report')$$,'pending report retries are idempotent');
select is((select count(*)::int from public.campus_circle_reports),1,'reporter can read own report');
select is(public.list_campus_circles()->0->>'reports','0','ordinary circle payload hides moderation data');
reset role;
select set_config('request.jwt.claim.sub','fdf00000-0000-4000-8000-000000000003',true);
set local role authenticated;
select throws_ok($$select public.act_campus_circle(current_setting('fixture.circle')::uuid,'join')$$,'P0001','circle_full','capacity cannot be exceeded');
select is((select count(*)::int from public.campus_circle_reports),0,'other students cannot read private reports');
select throws_ok($$insert into public.campus_circle_members(circle_id,user_id)values(current_setting('fixture.circle')::uuid,'fdf00000-0000-4000-8000-000000000003')$$,'42501',null,'direct membership inserts cannot bypass seat locks');
select throws_ok($$select public.act_campus_circle(current_setting('fixture.circle')::uuid,'dismiss')$$,'42501',null,'student cannot dismiss reports');
reset role;
select set_config('request.jwt.claim.sub','fdf00000-0000-4000-8000-000000000002',true);
set local role authenticated;
select lives_ok($$select public.act_campus_circle(current_setting('fixture.circle')::uuid,'leave')$$,'student can release seat');
reset role;
select set_config('request.jwt.claim.sub','fdf00000-0000-4000-8000-000000000003',true);
set local role authenticated;
select lives_ok($$select public.act_campus_circle(current_setting('fixture.circle')::uuid,'join')$$,'released seat becomes available');
reset role;
select set_config('request.jwt.claim.sub','fdf00000-0000-4000-8000-000000000004',true);
set local role authenticated;
select is(public.list_campus_circles()->0->>'reports','1','admin can see pending report count');
select is(public.list_campus_circles()->0->>'moderation_note','Please inspect this gathering','admin sees private report reason');
select lives_ok($$select public.act_campus_circle(current_setting('fixture.circle')::uuid,'close')$$,'admin can close reported gathering');
select is((select status from public.campus_circle_reports limit 1),'resolved','closing resolves reports');
reset role;
select set_config('request.jwt.claim.sub','',true);
set local role anon;
select is(jsonb_array_length(public.list_campus_circles()),0,'closed circle leaves public square');
select is(jsonb_array_length(public.list_campus_circles(false,current_setting('fixture.circle')::uuid)),0,'anonymous direct link cannot reveal closed circle');
select throws_ok($$select public.save_companion_section('tasks','[]',0)$$,'42501',null,'anonymous cannot save private data');
select throws_ok($$select public.create_campus_circle('{}')$$,'42501',null,'anonymous cannot host gatherings');
select throws_ok($$select * from public.companion_sections$$,'42501',null,'anonymous cannot query private data');
reset role;
select set_config('request.jwt.claim.sub','fdf00000-0000-4000-8000-000000000004',true);
set local role authenticated;
select is((select count(*)::int from public.companion_sections),0,'an application admin cannot read other students personal plans');
reset role;
select set_config('request.jwt.claim.sub','fdf00000-0000-4000-8000-000000000001',true);
set local role authenticated;
select throws_ok($$select public.create_campus_circle(jsonb_build_object('title','Expired gathering','description','An expired gathering fixture.','kind','study','location','Library tables','starts_at',now()-interval '1 day','duration',25,'capacity',2))$$,'P0001','circle_ended','hosting cannot create past gatherings');
select throws_ok($$select public.create_campus_circle(jsonb_build_object('title','Far future gathering','description','A far future gathering fixture.','kind','study','location','Library tables','starts_at',now()+interval '91 days','duration',25,'capacity',2))$$,'P0001','circle_ended','hosting is bounded to ninety days');
select throws_ok($$update public.campus_circles set capacity=12$$,'42501',null,'direct circle edits cannot bypass server rules');
select lives_ok($action$do $$begin for i in 1..4 loop perform public.create_campus_circle(jsonb_build_object('title','Limited host gathering','description','A daily hosting limit fixture.','kind','study','location','Library tables','starts_at',now()+interval '1 day','duration',25,'capacity',2));end loop;end;$$$action$,'host can create up to five gatherings');
select throws_ok($$select public.create_campus_circle(jsonb_build_object('title','Sixth gathering attempt','description','An over-limit gathering fixture.','kind','study','location','Library tables','starts_at',now()+interval '1 day','duration',25,'capacity',2))$$,'P0001','circle_limit','sixth creation in twenty-four hours is rejected');
select is(jsonb_array_length(public.list_campus_circles(true)),5,'host history includes their closed gatherings');
reset role;
update public.campus_circles set status='open',starts_at=now()-interval '1 day' where id=current_setting('fixture.circle')::uuid;
select set_config('request.jwt.claim.sub','fdf00000-0000-4000-8000-000000000002',true);
set local role authenticated;
select throws_ok($$select public.act_campus_circle(current_setting('fixture.circle')::uuid,'join')$$,'P0001','circle_ended','expired gatherings do not accept new joins');
reset role;
select * from finish();
rollback;
